function TakeButton() {
  const camera = useCamera();
  return (
    <Button onPress={camera.press} disabled={!camera.ready} loading={camera.capturing}>
      {camera.countdown ? `${camera.countdown}` : 'Take photo'}
    </Button>
  );
}

<Camera onCapture={keep}>
  <Camera.Preview />
  <Camera.Footer>
    <TakeButton />
  </Camera.Footer>
</Camera>
